def seed_timesheet_categories(apps, schema_editor):
    TimesheetCategory = apps.get_model("db", "TimesheetCategory")
    for key, name, description, sort_order, is_active in TIMESHEET_CATEGORY_SEED:
        TimesheetCategory.objects.update_or_create(
            key=key,
            defaults={
                "name": name,
                "description": description,
                "sort_order": sort_order,
                "is_active": is_active,
                "is_system": True,
            },
        )


